class Solution { public:long long minimumCost(string source,string target,vector<char>& original,vector<char>& changed,vector<int>& cost){const long long INF=LLONG_MAX/4;long long distance[26][26];for(int from=0;from<26;++from)for(int to=0;to<26;++to)distance[from][to]=from==to?0:INF;for(int i=0;i<(int)cost.size();++i){int from=original[i]-'a',to=changed[i]-'a';distance[from][to]=min(distance[from][to],1LL*cost[i]);}for(int middle=0;middle<26;++middle)for(int from=0;from<26;++from)for(int to=0;to<26;++to)if(distance[from][middle]<INF&&distance[middle][to]<INF)distance[from][to]=min(distance[from][to],distance[from][middle]+distance[middle][to]);long long answer=0;for(int i=0;i<(int)source.size();++i){long long value=distance[source[i]-'a'][target[i]-'a'];if(value==INF)return -1;answer+=value;}return answer;} };
